// The BigQuery node emits ~35 rows (one per segment value). Everything
// downstream needs to run ONCE, not 35 times, so they are collapsed into a
// single item here. The period window travels with them, so the data table
// read and the renderer take the window from the same source as the numbers.
const rows = $input.all().map((i) => i.json);
if (!rows.length) throw new Error('Segmented score query returned no rows - check the BigQuery node');

const overall = rows.find((r) => r.segment_dim === 'overall' && r.segment_value === 'all') || {};
const label = overall.period_label || rows[0].period_label || '';

// Derive the window from the label rather than trusting a second date
// calculation to agree with the SQL one.
const d = new Date(`${label} 1 UTC`);
const start = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1));
const end = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0));
// The prior month is fetched in the SAME data table call and split in the
// engine, rather than issuing a second read.
const priorStart = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() - 1, 1));
const iso = (x) => x.toISOString().slice(0, 10);

// A segment value whose score is built on very few responses gets its derived
// ratios nulled rather than shown. Embed tier (n=2) otherwise reports a
// writer_bias of -200, which is arithmetically true and completely meaningless.
const MIN_SCORE_N = 30;

// NPS is a difference of two proportions, so its sampling error is
// 100*sqrt((p + d - (p-d)^2)/n). A month-over-month delta combines two such
// errors.
const num = (v) => { const x = Number(v); return isFinite(x) ? x : 0; };

// A REAL p-value for the month-over-month change, so the stars in the score
// table mean exactly what the stars in the findings table mean. Relabelling a
// noise band as stars would make two different statistics look identical.
function erf(x) {
  const sg = x < 0 ? -1 : 1;
  x = Math.abs(x);
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741,
        a4 = -1.453152027, a5 = 1.061405429, pp = 0.3275911;
  const t = 1 / (1 + pp * x);
  const y = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return sg * y;
}
const normalCdf = (z) => 0.5 * (1 + erf(z / Math.SQRT2));

function npsStdErr(promoters, detractors, n) {
  if (!n) return null;
  const p = num(promoters) / n, d = num(detractors) / n;
  const v = (p + d - Math.pow(p - d, 2)) / n;
  return v > 0 ? 100 * Math.sqrt(v) : 0;
}

const scores = rows.map((r) => {
  const n = num(r.responses);
  if (n < MIN_SCORE_N) {
    return { ...r, score_reliable: false, writer_bias: null, nps_delta: null, pct_with_text: null, noise_band: null, delta_p: null, delta_moved: null };
  }
  const nPrior = num(r.responses_prior);
  const seCur = npsStdErr(r.promoters, r.detractors, n);
  const sePrior = nPrior >= MIN_SCORE_N ? npsStdErr(r.promoters_prior, r.detractors_prior, nPrior) : null;

  // No usable prior month means no verdict, rather than a delta presented bare.
  if (sePrior === null || r.nps_prior === null || r.nps_prior === undefined) {
    return { ...r, score_reliable: true, noise_band: null, delta_p: null, delta_moved: null };
  }
  const seCombined = Math.sqrt(seCur * seCur + sePrior * sePrior);
  const band = Math.round(1.96 * seCombined * 10) / 10;
  const z = seCombined > 0 ? Math.abs(num(r.nps_delta)) / seCombined : 0;
  const pDelta = 2 * (1 - normalCdf(z));
  // Same 0.05 threshold as the findings table, so 'significant' means one
  // thing across the whole report.
  const moved = pDelta < 0.05;
  return { ...r, score_reliable: true, noise_band: band, delta_p: pDelta, delta_moved: moved };
});

return [{ json: {
  period_label: label,
  period_start: iso(start),
  period_end: iso(end),
  prior_start: iso(priorStart),
  overall,
  scores,
  min_score_n: MIN_SCORE_N,
} }];

// ===================================================================
// PERIOD ANALYSIS - global + segmented, one deterministic pass.
// The LLM never counts and never decides what is a finding. Selection
// is arithmetic, so rerunning the same month gives the same answers.
// ===================================================================

const SEGMENT_DIMS = ['deployment', 'enterprise_tier', 'role', 'company_size', 'tech_skills_count'];
const MIN_SEGMENT_ROWS = 30;
const MIN_EXPECTED_COUNT = 5;
const FDR_Q = 0.05;

const ALL_PILLARS = ['AI Building', 'Visual Auditability', 'Runtime Governance', 'Power & Ceiling', 'Setup & Activation', 'Agents vs Workflows', 'Self-hosting & Openness', 'Community & Ecosystem'];
// Configure-once surfaces: users touch them rarely, so they generate almost no
// unprompted comment however important they are. A zero is EXPECTED and is not
// evidence of health - flagged in the data so the report cannot imply it is.
const CONFIGURE_ONCE_PILLARS = ['Runtime Governance', 'Setup & Activation'];

function erf(x) {
  const s = x < 0 ? -1 : 1;
  x = Math.abs(x);
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741,
        a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const t = 1 / (1 + p * x);
  const y = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return s * y;
}
const normalCdf = (z) => 0.5 * (1 + erf(z / Math.SQRT2));

// Tested against THE REST of the population, not the overall total: a segment is
// a subset of the overall, so comparing to it compares a group with itself.
function twoProportionTest(k1, n1, k2, n2) {
  if (!n1 || !n2) return null;
  const p1 = k1 / n1, p2 = k2 / n2;
  const pPool = (k1 + k2) / (n1 + n2);
  if (pPool <= 0 || pPool >= 1) return null;
  if (n1 * pPool < MIN_EXPECTED_COUNT || n2 * pPool < MIN_EXPECTED_COUNT) return null;
  const se = Math.sqrt(pPool * (1 - pPool) * (1 / n1 + 1 / n2));
  if (!se) return null;
  const z = (p1 - p2) / se;
  return { z, pValue: 2 * (1 - normalCdf(Math.abs(z))), share: p1, restShare: p2, diffPct: (p1 - p2) * 100 };
}

// WITHOUT THIS THE WHOLE THING IS THEATRE: ~150-300 simultaneous tests at raw
// p<0.05 manufacture roughly 15 'findings' a month from noise.
function benjaminiHochberg(tests, q) {
  const sorted = [...tests].sort((a, b) => a.pValue - b.pValue);
  const m = sorted.length;
  let maxRank = 0;
  sorted.forEach((t, i) => { if (t.pValue <= ((i + 1) / m) * q) maxRank = i + 1; });
  const cutoff = maxRank > 0 ? sorted[maxRank - 1].pValue : -1;
  for (const t of tests) t.significant = maxRank > 0 && t.pValue <= cutoff;
  return { m, passed: maxRank, cutoff };
}

const norm = (s) => String(s).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '').replace(/\s+/g, ' ').trim();
const NPS_BAND = (n) => { const s = Number(n); if (s <= 6) return 'detractors'; if (s <= 8) return 'passives'; return 'promoters'; };
const validEvidence = (ev) => ev && ev !== 'UNMATCHED_BY_CLASSIFIER' && !String(ev).startsWith('ENUM_VIOLATION');
const pctOf = (k, n) => (n ? Math.round(1000 * k / n) / 10 : 0);

function collapseWithNps(list, cap) {
  const m = new Map();
  for (const it of list) {
    const k = norm(it.text);
    if (!k) continue;
    if (!m.has(k)) m.set(k, { text: it.text, count: 0, npsSum: 0, negativeCount: 0 });
    const e = m.get(k);
    e.count++;
    e.npsSum += Number(it.nps) || 0;
    if (it.negative) e.negativeCount++;
  }
  return [...m.values()]
    .map((e) => ({ text: e.text, count: e.count, avg_nps: Math.round(e.npsSum / e.count * 10) / 10, negativeCount: e.negativeCount }))
    .sort((a, b) => b.count - a.count)
    .slice(0, cap);
}

function sentimentSplit(counts) {
  const pos = counts.positive || 0, neg = counts.negative || 0, neu = counts.neutral || 0;
  const t = pos + neg + neu;
  return { total: t, positive_pct: pctOf(pos, t), negative_pct: pctOf(neg, t), neutral_pct: pctOf(neu, t) };
}

// ===================================================================
// GLOBAL ANALYSIS: topics, requests, complaints, strategic bets
// ===================================================================
function buildOverallReport(rows) {
  const n = rows.length;
  const catStats = {};
  const ensure = (name) => {
    if (!catStats[name]) catStats[name] = {
      category: name, primary: 0, secondary: 0, detractors: 0, passives: 0, promoters: 0,
      sentimentCounts: { positive: 0, negative: 0, neutral: 0 }, _requests: [], _problems: [],
    };
    return catStats[name];
  };

  let unmatched_rows = 0, enum_violation_rows = 0, other_rows = 0;
  const allRequests = [], allProblems = [];

  for (const r of rows) {
    const cat = r.category || 'Other';
    const c = ensure(cat);
    c.primary++;
    c[NPS_BAND(r.nps)]++;
    if (r.sentiment && c.sentimentCounts[r.sentiment] !== undefined) c.sentimentCounts[r.sentiment]++;
    if (r.category_secondary) ensure(r.category_secondary).secondary++;

    const ev = String(r.evidence || '').trim();
    if (ev === 'UNMATCHED_BY_CLASSIFIER') unmatched_rows++;
    if (ev.startsWith('ENUM_VIOLATION')) enum_violation_rows++;
    if (cat === 'Other') other_rows++;

    if (validEvidence(ev)) {
      const entry = { text: ev, nps: r.nps, negative: r.sentiment === 'negative' };
      if (r.is_request === true) { c._requests.push(entry); allRequests.push(entry); }
      else { c._problems.push(entry); allProblems.push(entry); }
    }
  }

  const categories = Object.values(catStats)
    .sort((a, b) => (b.primary + b.secondary) - (a.primary + a.secondary))
    .map((c) => {
      delete c._requests; delete c._problems;
      return {
        ...c, mentions: c.primary + c.secondary, share_pct: pctOf(c.primary, n),
        sentiment: sentimentSplit(c.sentimentCounts),
        interpretable: (c.primary + c.secondary) >= MIN_SEGMENT_ROWS,
      };
    });

  // Requests and complaints are DIFFERENT things for a product team: what people
  // asked for versus what they struggled with. Complaints are the negative
  // subset of problems, derived with a flag rather than a duplicated array.
  const topRequests = collapseWithNps(allRequests, 15);
  const topComplaints = collapseWithNps(allProblems.filter((x) => x.negative), 15);

  const mkPillar = (p) => ({ pillar: p, mentions: 0, sentimentCounts: { positive: 0, negative: 0, neutral: 0 } });
  const pillarStats = {};
  for (const p of ALL_PILLARS) pillarStats[p] = mkPillar(p);
  const byDep = { cloud: {}, self_hosted: {} };
  for (const dep of Object.keys(byDep)) for (const p of ALL_PILLARS) byDep[dep][p] = mkPillar(p);

  let pillar_none_count = 0;
  const depTotals = { cloud: 0, self_hosted: 0 };
  const depNone = { cloud: 0, self_hosted: 0 };

  for (const r of rows) {
    const dep = r.deployment === 'cloud' || r.deployment === 'self_hosted' ? r.deployment : null;
    if (dep) depTotals[dep]++;
    const p = r.strategy_pillar;
    if (!p || p === 'None' || !pillarStats[p]) {
      pillar_none_count++;
      if (dep) depNone[dep]++;
      continue;
    }
    pillarStats[p].mentions++;
    if (r.sentiment && pillarStats[p].sentimentCounts[r.sentiment] !== undefined) pillarStats[p].sentimentCounts[r.sentiment]++;
    if (dep) {
      byDep[dep][p].mentions++;
      if (r.sentiment && byDep[dep][p].sentimentCounts[r.sentiment] !== undefined) byDep[dep][p].sentimentCounts[r.sentiment]++;
    }
  }

  const dress = (x, total) => ({
    ...x, share_pct: pctOf(x.mentions, total), sentiment: sentimentSplit(x.sentimentCounts),
    interpretable: x.mentions >= MIN_SEGMENT_ROWS, configure_once: CONFIGURE_ONCE_PILLARS.includes(x.pillar),
  });
  const pillars = Object.values(pillarStats).sort((a, b) => b.mentions - a.mentions).map((x) => dress(x, n));

  // Pillar x deployment, TESTED rather than merely displayed: is this bet
  // discussed more by one deployment group than the other?
  const pillarContrasts = [];
  for (const p of ALL_PILLARS) {
    const t = twoProportionTest(byDep.cloud[p].mentions, depTotals.cloud, byDep.self_hosted[p].mentions, depTotals.self_hosted);
    if (!t) continue;
    pillarContrasts.push({
      pillar: p,
      cloud_pct: Math.round(t.share * 1000) / 10, cloud_count: byDep.cloud[p].mentions,
      self_hosted_pct: Math.round(t.restShare * 1000) / 10, self_hosted_count: byDep.self_hosted[p].mentions,
      diffPct: Math.round(t.diffPct * 10) / 10, pValue: t.pValue, significant: false,
    });
  }
  benjaminiHochberg(pillarContrasts, FDR_Q);

  return {
    driver_responses: n, categories, topRequests, topComplaints, pillars,
    pillarContrasts: pillarContrasts.filter((c) => c.significant),
    pillar_none_count, pillar_none_share_pct: pctOf(pillar_none_count, n),
    // How much of each group's feedback lands outside everything we bet on.
    pillar_none_by_deployment: { cloud: pctOf(depNone.cloud, depTotals.cloud), self_hosted: pctOf(depNone.self_hosted, depTotals.self_hosted) },
    quality: {
      unmatched_rows, enum_violation_rows, other_rows,
      strategy_versions: [...new Set(rows.map((r) => r.strategy_version).filter(Boolean))].sort(),
      approx_timestamp_rows: rows.filter((r) => r.backfilled === null || r.backfilled === undefined).length,
    },
  };
}

// ===================================================================
// SEGMENTED ANALYSIS
// ===================================================================
const STRATIFIER = 'deployment';
const chiSqP1df = (x2) => (x2 <= 0 ? 1 : 2 * (1 - normalCdf(Math.sqrt(x2))));

function mantelHaenszel(strata) {
  let sumA = 0, sumE = 0, sumV = 0, used = 0;
  for (const s of strata) {
    const N = s.n1 + s.n2;
    if (N < 2) continue;
    const m1 = s.a + s.b, m2 = N - m1;
    if (m1 === 0 || m2 === 0) continue;
    if (s.n1 < MIN_SEGMENT_ROWS || s.n2 < MIN_SEGMENT_ROWS) continue;
    sumA += s.a;
    sumE += (s.n1 * m1) / N;
    sumV += (s.n1 * s.n2 * m1 * m2) / (N * N * (N - 1));
    used++;
  }
  if (!used || sumV <= 0) return { testable: false, strataUsed: used };
  const x2 = Math.pow(Math.abs(sumA - sumE), 2) / sumV;
  return { testable: true, strataUsed: used, pValue: chiSqP1df(x2), direction: sumA >= sumE ? 'more' : 'less' };
}

// A certified contrast says a segment talks about X more. It does NOT say the
// segment is the cause: roles and company sizes skew hard by deployment, so a
// role effect can be a deployment effect wearing a costume.
function stratifyContrasts(usable, certified) {
  const strataValues = [...new Set(usable.map((r) => r[STRATIFIER]).filter(Boolean))];
  for (const c of certified) {
    if (c.dimension === STRATIFIER) {
      c.deployment_check = 'not_applicable';
      c.deployment_check_note = 'This IS the deployment split, so there is nothing to hold constant.';
      continue;
    }
    if (c.dimension === 'tech_skills_count') {
      c.deployment_check = 'not_applicable';
      c.deployment_check_note = 'Technical skills is a cloud-only question, so this effect is already inside one deployment group.';
      continue;
    }
    const strata = strataValues.map((sv) => {
      const inS = usable.filter((r) => r[STRATIFIER] === sv);
      const inV = inS.filter((r) => String(r[c.dimension] ?? 'NA') === c.value);
      const rest = inS.filter((r) => String(r[c.dimension] ?? 'NA') !== c.value);
      return {
        a: inV.filter((r) => (r.category || 'Other') === c.category).length, n1: inV.length,
        b: rest.filter((r) => (r.category || 'Other') === c.category).length, n2: rest.length,
      };
    });
    const mh = mantelHaenszel(strata);
    // A verdict needs TWO strata. With one, the segment sits almost entirely
    // inside a single deployment group and the two cannot be told apart.
    if (!mh.testable || mh.strataUsed < 2) {
      c.deployment_check = 'undetermined';
      c.deployment_check_note = mh.strataUsed === 1
        ? 'This segment sits almost entirely within one deployment group, so its effect cannot be separated from cloud vs self-hosted.'
        : `Too few responses once split by deployment to tell whether this is a ${c.dimension} effect or a deployment effect.`;
      continue;
    }
    if (mh.pValue < 0.05 && mh.direction === (c.diffPct > 0 ? 'more' : 'less')) {
      c.deployment_check = 'independent';
      c.deployment_check_note = 'Holds up within cloud and self-hosted separately, so it is not just a deployment difference.';
    } else {
      c.deployment_check = 'explained_by_deployment';
      c.deployment_check_note = 'Disappears once deployment is held constant - most likely a cloud vs self-hosted effect, not a genuine one for this segment.';
    }
  }
}

// tech_skills_count='NA' is EXACTLY self_hosted, so testing both ran identical
// arithmetic twice and printed it as two findings. Detected structurally, so
// any future pair that collapses onto the same rows is caught too.
function findAliases(usable, dims) {
  const sig = new Map();
  for (const dim of dims) {
    const groups = new Map();
    usable.forEach((r, i) => {
      const v = r[dim] === null || r[dim] === undefined || r[dim] === '' ? 'NA' : String(r[dim]);
      if (!groups.has(v)) groups.set(v, []);
      groups.get(v).push(i);
    });
    for (const [v, idx] of groups.entries()) {
      if (idx.length < 2) continue;
      const k = idx.join(',');
      if (!sig.has(k)) sig.set(k, []);
      sig.get(k).push({ dimension: dim, value: v });
    }
  }
  const aliasOf = new Map();
  for (const members of sig.values()) {
    if (members.length < 2) continue;
    for (const m of members.slice(1)) aliasOf.set(`${m.dimension}||${m.value}`, members[0]);
  }
  return aliasOf;
}

function buildSegmentReport(rows, segmentScores) {
  const usable = rows.filter((r) => r.deployment !== null && r.deployment !== undefined && r.deployment !== '');
  const uncaptured = rows.length - usable.length;
  const scoreIndex = {};
  for (const s of segmentScores || []) scoreIndex[`${s.segment_dim}||${s.segment_value}`] = s;

  const aliasOf = findAliases(usable, SEGMENT_DIMS);
  const allTests = [];
  const dimensions = [];

  for (const dim of SEGMENT_DIMS) {
    const byValue = new Map();
    for (const r of usable) {
      const v = r[dim] === null || r[dim] === undefined || r[dim] === '' ? 'NA' : String(r[dim]);
      if (!byValue.has(v)) byValue.set(v, []);
      byValue.get(v).push(r);
    }
    const overallCat = {};
    for (const r of usable) overallCat[r.category || 'Other'] = (overallCat[r.category || 'Other'] || 0) + 1;
    const overallN = usable.length;

    const values = [];
    for (const [value, vRows] of byValue.entries()) {
      const n = vRows.length;
      const catCounts = {};
      const sentiment = { positive: 0, negative: 0, neutral: 0 };
      const bands = { detractors: 0, passives: 0, promoters: 0 };
      const reqs = [], probs = [], quotes = [];
      for (const r of vRows) {
        catCounts[r.category || 'Other'] = (catCounts[r.category || 'Other'] || 0) + 1;
        if (sentiment[r.sentiment] !== undefined) sentiment[r.sentiment]++;
        bands[NPS_BAND(r.nps)]++;
        const ev = String(r.evidence || '').trim();
        if (validEvidence(ev)) {
          if (r.is_request === true) reqs.push({ text: ev, nps: r.nps });
          else probs.push({ text: ev, nps: r.nps, negative: r.sentiment === 'negative' });
          if (r.actionable === true) quotes.push({ text: r.feedback, evidence: ev, nps: Number(r.nps) });
        }
      }
      const alias = aliasOf.get(`${dim}||${value}`) || null;
      const testable = n >= MIN_SEGMENT_ROWS && !alias;
      const contrasts = [];
      if (testable) {
        for (const [cat, k] of Object.entries(catCounts)) {
          const t = twoProportionTest(k, n, (overallCat[cat] || 0) - k, overallN - n);
          if (!t) continue;
          const rec = {
            dimension: dim, value, category: cat, count: k,
            sharePct: Math.round(t.share * 1000) / 10,
            restSharePct: Math.round(t.restShare * 1000) / 10,
            diffPct: Math.round(t.diffPct * 10) / 10,
            pValue: t.pValue, significant: false,
          };
          contrasts.push(rec);
          allTests.push(rec);
        }
      }
      const byBand = { detractors: [], passives: [], promoters: [] };
      for (const q of quotes) byBand[NPS_BAND(q.nps)].push(q);
      values.push({
        value, rows: n, testable, alias_of: alias,
        suppressed_reason: alias
          ? `identical to ${alias.dimension} = ${alias.value} (exactly the same responses), so it is reported there rather than counted twice`
          : (testable ? '' : `only ${n} classified responses, below the ${MIN_SEGMENT_ROWS} floor - counts shown, no claims made`),
        score: scoreIndex[`${dim}||${value}`] || null,
        categoryCounts: catCounts, sentimentCounts: sentiment, npsBands: bands,
        requestPhrases: collapseWithNps(reqs, 10),
        problemPhrases: collapseWithNps(probs, 10),
        quoteCandidates: [...byBand.detractors.slice(0, 3), ...byBand.promoters.slice(0, 2)].slice(0, 4),
        contrasts,
      });
    }
    values.sort((a, b) => b.rows - a.rows);
    dimensions.push({ dimension: dim, values });
  }

  const fdr = benjaminiHochberg(allTests, FDR_Q);
  const certified = allTests.filter((t) => t.significant);
  stratifyContrasts(usable, certified);

  const byCategory = {};
  for (const t of certified) {
    if (!byCategory[t.category]) byCategory[t.category] = new Set();
    byCategory[t.category].add(t.dimension);
  }
  for (const t of certified) t.alsoSignificantIn = [...(byCategory[t.category] || [])].filter((d) => d !== t.dimension);

  return {
    dimensions,
    certified_contrasts: certified.sort((a, b) => {
      const rank = (x) => {
        if (x.deployment_check === 'independent') return 0;
        if (x.deployment_check === 'not_applicable' && x.dimension === 'deployment') return 0;
        if (x.deployment_check === 'not_applicable') return 1;
        if (x.deployment_check === 'undetermined') return 2;
        return 3;
      };
      return rank(a) - rank(b) || Math.abs(b.diffPct) - Math.abs(a.diffPct);
    }),
    stats: {
      classified_rows: rows.length, segmented_rows: usable.length, uncaptured_rows: uncaptured,
      coverage_pct: rows.length ? Math.round(1000 * usable.length / rows.length) / 10 : 0,
      tests_run: fdr.m, tests_passed: fdr.passed, fdr_q: FDR_Q, min_segment_rows: MIN_SEGMENT_ROWS,
      aliased_values: aliasOf.size,
      independent_findings: certified.filter((c) => c.deployment_check === 'independent').length,
      explained_by_deployment: certified.filter((c) => c.deployment_check === 'explained_by_deployment').length,
      undetermined_findings: certified.filter((c) => c.deployment_check === 'undetermined').length,
    },
  };
}

// ---- entry point ----
const rows = $input.all().map((i) => i.json);
const bundle = $('Collect Segment Scores').first().json;
if (!rows.length) throw new Error('No classified rows for ' + bundle.period_label + ' - has the backfill run for this period?');

const report = buildSegmentReport(rows, bundle.scores);
report.overall = buildOverallReport(rows);
const st = report.stats;
console.log('[Analysis] ' + report.overall.driver_responses + ' comments, ' + report.overall.categories.length + ' topics, ' + report.overall.pillar_none_share_pct + '% touched no current bet');
console.log('[Segments] ' + st.segmented_rows + '/' + st.classified_rows + ' segmented (' + st.coverage_pct + '%), ' + st.tests_passed + '/' + st.tests_run + ' contrasts certified, ' + st.independent_findings + ' independent of deployment');

return [{ json: report }];

// One item per segment dimension, so the loop below makes one LLM call per
// dimension rather than one per segment VALUE (~35 calls, far more variance
// between runs and no extra insight).
//
// Reads the engine BY NAME rather than from $json: the theme clustering step
// now sits between the engine and this node, so $json here is the theme
// assignments, not the segment report.
const report = $('Segment Contrast Engine').first().json;
const scoreBundle = $('Collect Segment Scores').first().json;

return report.dimensions.map((d) => ({ json: {
  dimension: d.dimension,
  period_label: scoreBundle.period_label,
  values: d.values,
  certified: report.certified_contrasts.filter((c) => c.dimension === d.dimension),
  stats: report.stats,
} }));

// Renders Slack and the full report from ONE payload, so the short and long
// versions cannot drift apart. Global analysis first, then segmented.

const NOTION_MAIN_PAGE_URL = '';
const NOTION_MONTHLY_DB_URL = '';

const narrations = $input.all().map((i) => i.json);
const report = $('Segment Contrast Engine').first().json;
const bundle = $('Collect Segment Scores').first().json;
const themes = $('Parse Theme Assignments').first().json;
const period = bundle.period_label;
const st = report.stats;
const ov = report.overall;

// BigQuery returns numerics as STRINGS in n8n ("45406", "62.1"), so this must
// COERCE rather than type-check.
const n = (v) => { const x = typeof v === 'string' ? Number(v) : v; return (typeof x === 'number' && isFinite(x)) ? x : 0; };
const s = (v) => (typeof v === 'string' ? v : '');
const num = (v) => n(v).toLocaleString('en-US');
const stars = (p) => (p < 0.001 ? '***' : p < 0.01 ? '**' : '*');
const byDim = {};
for (const x of narrations) byDim[x.dimension] = x;

const DIM_LABEL = {
  deployment: 'Cloud vs self-hosted',
  enterprise_tier: 'Enterprise tier',
  role: 'Role',
  company_size: 'Company size',
  tech_skills_count: 'Technical skills (cloud only)',
};
const failed = narrations.filter((x) => !x.parse_ok).map((x) => x.dimension);
const overallScore = bundle.scores.find((x) => x.segment_dim === 'overall');
const reliable = bundle.scores.filter((x) => x.score_reliable);

const mdTable = (cols, rows) => {
  if (!rows.length) return '_Nothing to show._';
  return [`| ${cols.map((c) => c.label).join(' | ')} |`, `| ${cols.map(() => '---').join(' | ')} |`,
    ...rows.map((r) => `| ${cols.map((c) => String(r[c.key] ?? '')).join(' | ')} |`)].join('\n');
};
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const htmlTable = (cols, rows) => {
  if (!rows.length) return '<p><em>Nothing to show.</em></p>';
  const th = cols.map((c) => `<th align="left" style="padding:6px 10px;border-bottom:2px solid #333;">${esc(c.label)}</th>`).join('');
  const tr = rows.map((r, i) => `<tr${i % 2 ? ' style="background:#fafafa;"' : ''}>${cols.map((c) => `<td style="padding:6px 10px;border-bottom:1px solid #eee;">${esc(r[c.key])}</td>`).join('')}</tr>`).join('');
  return `<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;font-size:13px;width:100%;"><thead><tr>${th}</tr></thead><tbody>${tr}</tbody></table>`;
};

// ================= THEME TABLES =================
// Rows are curated themes, not raw phrases. A phrase can belong to more than
// one theme, so shares do NOT sum to 100% - each is the share of comments
// MENTIONING that theme, not a slice of a pie.
const themeRows = (list, unassigned) => {
  const rows = (list || []).map((t) => ({
    theme: s(t.label),
    mentions: num(t.mentions),
    share: `${t.share_pct}%`,
    phrases: num(t.distinct_phrases),
    avg: String(t.avg_nps),
    examples: (t.samples || []).slice(0, 2).map((x) => s(x)).join(' | '),
  }));
  if (unassigned && unassigned.mentions > 0) {
    rows.push({
      theme: 'Unassigned - fits no current theme',
      mentions: num(unassigned.mentions),
      share: `${unassigned.pct}%`,
      phrases: '', avg: '',
      examples: 'Review these: they may need a new theme in the codebook',
    });
  }
  return rows;
};
const THEME_COLS = [
  { key: 'theme', label: 'Theme' }, { key: 'mentions', label: 'Mentions' }, { key: 'share', label: 'Share' },
  { key: 'phrases', label: 'Distinct phrasings' }, { key: 'avg', label: 'Avg NPS' }, { key: 'examples', label: 'Examples' },
];
const requestRows = themeRows(themes.request_themes, themes.unassigned && themes.unassigned.request);
const complaintRows = themeRows(themes.complaint_themes, themes.unassigned && themes.unassigned.complaint);
const THEME_FOOTNOTE = 'Themes come from a fixed codebook, so they mean the same thing month to month. A comment can mention more than one theme, so shares do not add up to 100% - each is the share of comments mentioning that theme.';

// The alert: users are talking about something the codebook does not cover.
const alertLines = [];
if (themes.alert) {
  const u = themes.unassigned || {};
  const parts = [];
  if (u.request && u.request.pct > themes.alert_threshold_pct) parts.push(`${u.request.pct}% of requests`);
  if (u.complaint && u.complaint.pct > themes.alert_threshold_pct) parts.push(`${u.complaint.pct}% of complaints`);
  alertLines.push(`${parts.join(' and ')} did not fit any theme in the codebook (threshold ${themes.alert_threshold_pct}%). Review the unassigned rows before treating this month as final - they may need a new theme.`);
}
if (!themes.ok) alertLines.push('Theme clustering failed this run, so the request and complaint tables are empty. Everything else is unaffected.');

// ================= GLOBAL TABLES =================
const topicRows = (ov.categories || []).map((c) => ({
  topic: s(c.category), mentions: num(c.mentions), share: `${c.share_pct}%`,
  sentiment: c.sentiment.total ? `${c.sentiment.positive_pct}% pos / ${c.sentiment.negative_pct}% neg` : '-',
  bands: `${num(c.detractors)} / ${num(c.passives)} / ${num(c.promoters)}`,
  note: c.interpretable ? '' : 'too few to interpret',
}));
const TOPIC_COLS = [
  { key: 'topic', label: 'Topic' }, { key: 'mentions', label: 'Mentions' }, { key: 'share', label: 'Share' },
  { key: 'sentiment', label: 'Sentiment' }, { key: 'bands', label: 'Detr / Pass / Prom' }, { key: 'note', label: 'Notes' },
];

const contrastByPillar = {};
for (const c of (ov.pillarContrasts || [])) contrastByPillar[c.pillar] = c;
let anyConfigureOnce = false;
const pillarRows = (ov.pillars || []).map((p) => {
  const c = contrastByPillar[p.pillar];
  if (p.configure_once) anyConfigureOnce = true;
  return {
    bet: `${s(p.pillar)}${p.configure_once ? ' \u2020' : ''}`,
    mentions: num(p.mentions), share: `${p.share_pct}%`,
    sentiment: p.sentiment.total ? `${p.sentiment.positive_pct}% pos / ${p.sentiment.negative_pct}% neg` : '-',
    split: c ? `cloud ${c.cloud_pct}% vs self-hosted ${c.self_hosted_pct}%${stars(c.pValue)}` : '',
    note: p.interpretable ? '' : 'too few to interpret',
  };
});
const PILLAR_COLS = [
  { key: 'bet', label: 'Strategic bet' }, { key: 'mentions', label: 'Mentions' }, { key: 'share', label: 'Share' },
  { key: 'sentiment', label: 'Sentiment' }, { key: 'split', label: 'Differs by deployment' }, { key: 'note', label: 'Notes' },
];
const CONFIGURE_ONCE_FOOTNOTE = '\u2020 Configure-once surface: users touch it rarely, so it generates almost no unprompted comment however important it is. A zero here is expected and is not a health signal - source these from sales, support and CS instead.';

// ================= SEGMENT TABLES =================
const VERDICT_MARK = { independent: 'YES', explained_by_deployment: 'NO - deployment', undetermined: 'CANNOT TELL', not_applicable: 'n/a' };
const commentCounts = {};
for (const d of report.dimensions) for (const v of d.values) commentCounts[`${d.dimension}||${v.value}`] = v;

const SEGMENT_ORDER = {
  company_size: ['solo', '<20', '20-99', '100-499', '500-999', '1000+', 'not_for_work', 'NA'],
  tech_skills_count: 'numeric',
};
function orderRows(dim, rows) {
  const spec = SEGMENT_ORDER[dim];
  if (!spec) return rows;
  if (spec === 'numeric') {
    return [...rows].sort((a, b) => {
      const av = Number(a.segment_value), bv = Number(b.segment_value);
      const aN = isFinite(av), bN = isFinite(bv);
      if (aN && bN) return av - bv;
      if (aN) return -1;
      if (bN) return 1;
      return String(a.segment_value).localeCompare(String(b.segment_value));
    });
  }
  return [...rows].sort((a, b) => {
    const ai = spec.indexOf(String(a.segment_value)), bi = spec.indexOf(String(b.segment_value));
    return (ai === -1 ? spec.length : ai) - (bi === -1 ? spec.length : bi) || n(b.responses) - n(a.responses);
  });
}

const scoreRows = [];
const suppressedAliases = [];
for (const dim of Object.keys(DIM_LABEL)) {
  for (const x of orderRows(dim, bundle.scores.filter((y) => y.segment_dim === dim))) {
    const gap = overallScore ? Math.round((n(x.nps) - n(overallScore.nps)) * 10) / 10 : null;
    let change = '-';
    if (!x.score_reliable) change = 'too few responses';
    else if (x.nps_delta === null || x.nps_delta === undefined) change = 'no prior month';
    else change = `${n(x.nps_delta) > 0 ? '+' : ''}${n(x.nps_delta)}${x.delta_moved ? stars(n(x.delta_p)) : ''}`;
    const cv = commentCounts[`${dim}||${s(x.segment_value)}`];
    if (cv && cv.alias_of) {
      const canon = bundle.scores.find((y) => y.segment_dim === cv.alias_of.dimension && y.segment_value === cv.alias_of.value);
      if (canon && n(canon.responses) === n(x.responses)) { suppressedAliases.push(`${DIM_LABEL[dim]} = ${s(x.segment_value)} (identical to ${cv.alias_of.value})`); continue; }
    }
    let comments = cv ? num(cv.rows) : '0';
    if (cv && !cv.testable && !cv.alias_of) comments = `${num(cv.rows)} (too few to test)`;
    scoreRows.push({
      dimension: DIM_LABEL[dim], group: s(x.segment_value), responses: num(x.responses),
      nps: x.score_reliable ? String(n(x.nps)) : '-',
      vs_average: x.score_reliable && gap !== null ? `${gap > 0 ? '+' : ''}${gap}` : '-',
      change, comments, wrote_text: x.score_reliable ? `${n(x.pct_with_text)}%` : '-',
    });
  }
}
const SCORE_COLS = [
  { key: 'dimension', label: 'Segment' }, { key: 'group', label: 'Group' }, { key: 'responses', label: 'Responses' },
  { key: 'nps', label: 'NPS' }, { key: 'vs_average', label: 'vs average' }, { key: 'change', label: 'Change since last month' },
  { key: 'wrote_text', label: 'Wrote text' }, { key: 'comments', label: 'Comments analysed' },
];

const findingRows = report.certified_contrasts.map((c) => ({
  dimension: DIM_LABEL[c.dimension] || c.dimension, group: s(c.value), topic: s(c.category),
  direction: c.diffPct > 0 ? 'more' : 'less',
  this_group: `${c.sharePct}%`, everyone_else: `${c.restSharePct}%`,
  responses: String(c.count), sig: stars(c.pValue), real_effect: VERDICT_MARK[c.deployment_check] || '',
}));
const FINDING_COLS = [
  { key: 'dimension', label: 'Segment' }, { key: 'group', label: 'Group' }, { key: 'topic', label: 'Topic' },
  { key: 'direction', label: 'More/less' }, { key: 'this_group', label: 'This group' }, { key: 'everyone_else', label: 'Everyone else' },
  { key: 'responses', label: 'n' }, { key: 'sig', label: 'Sig.' }, { key: 'real_effect', label: 'Survives deployment check' },
];

const results = { period, topics: topicRows, requests: requestRows, complaints: complaintRows, bets: pillarRows, scores: scoreRows, findings: findingRows, themes, stats: st };

// ================= SLACK =================
const L = [];
L.push(`*NPS monthly* \u00b7 ${period}`);
L.push('');
for (const a of alertLines) { L.push(`:warning: ${a}`); L.push(''); }
if (overallScore) {
  L.push(`*NPS ${n(overallScore.nps)}* \u00b7 ${num(overallScore.responses)} answered \u00b7 ${n(overallScore.pct_with_text)}% wrote text`);
  if (overallScore.delta_moved === true) L.push(`${n(overallScore.nps_delta) > 0 ? 'Up' : 'Down'} ${Math.abs(n(overallScore.nps_delta))} points since last month.`);
  else if (overallScore.delta_moved === false) L.push('Essentially unchanged since last month.');
  L.push('');
}
if ((themes.complaint_themes || []).length) {
  L.push('*What they struggle with*');
  for (const t of themes.complaint_themes.slice(0, 3)) L.push(`\u2022 ${s(t.label)} \u2014 ${num(t.mentions)} mentions (${t.share_pct}%)`);
  L.push('');
}
if ((themes.request_themes || []).length) {
  L.push('*What they asked for*');
  for (const t of themes.request_themes.slice(0, 3)) L.push(`\u2022 ${s(t.label)} \u2014 ${num(t.mentions)} mentions (${t.share_pct}%)`);
  L.push('');
}
L.push(`*${ov.pillar_none_share_pct}% of what they said touched no current strategic bet* (cloud ${ov.pillar_none_by_deployment.cloud}%, self-hosted ${ov.pillar_none_by_deployment.self_hosted}%)`);
L.push('');
const gaps = reliable
  .filter((x) => x.segment_dim !== 'overall' && s(x.segment_value) !== 'NA' && n(x.responses) >= 300 && overallScore)
  .map((x) => ({ x, gap: n(x.nps) - n(overallScore.nps) }))
  .sort((a, b) => Math.abs(b.gap) - Math.abs(a.gap));
if (gaps.length) {
  L.push('*Standing gaps between groups* _(long-running differences, not changes)_');
  for (const g of gaps.slice(0, 3)) {
    L.push(`\u2022 ${DIM_LABEL[g.x.segment_dim]}: ${s(g.x.segment_value)} \u2014 NPS ${n(g.x.nps)}, ${Math.abs(Math.round(g.gap * 10) / 10)} points ${g.gap > 0 ? 'above' : 'below'} the ${n(overallScore.nps)} average`);
  }
  L.push('');
}
const independent = report.certified_contrasts.filter((c) => c.deployment_check === 'independent');
if (independent.length) {
  L.push(`*What differs by segment* \u2014 ${st.independent_findings} of ${st.tests_passed} survive holding deployment constant`);
  const seen = new Set();
  for (const c of independent) {
    if (seen.has(c.category)) continue;
    seen.add(c.category);
    if (seen.size > 3) break;
    L.push(`\u2022 *${DIM_LABEL[c.dimension]}: ${s(c.value)}* \u2014 ${s(c.category)} ${c.diffPct > 0 ? 'more' : 'less'} than everyone else, ${c.sharePct}% vs ${c.restSharePct}%`);
  }
} else {
  L.push('*What differs by segment*');
  L.push('Nothing survived the deployment check this month. Segments talked about broadly the same things.');
}
if (failed.length) { L.push(''); L.push(`:rotating_light: *Pipeline issue* \u2014 no narrative returned for: ${failed.join(', ')}`); }
L.push('');
L.push(NOTION_MONTHLY_DB_URL ? `<${NOTION_MONTHLY_DB_URL}|Full report>` : '_Full report by email._');
const slack_text = L.join('\n');

// ================= MARKDOWN =================
const M = [];
M.push(`# NPS monthly report - ${period}`);
