M.push('');
M.push(mdTable(THEME_COLS, requestRows));
M.push('');
M.push(`_${THEME_FOOTNOTE}_`);
M.push('');
M.push('## What they struggle with');
M.push('');
M.push('_Negative-sentiment evidence. Distinct from requests above: things people described as problems, not things they asked for._');
M.push('');
M.push(mdTable(THEME_COLS, complaintRows));
M.push('');
M.push('## Strategic bets');
M.push('');
M.push(`**${num(ov.pillar_none_count)} comments (${ov.pillar_none_share_pct}%) touched no current strategic bet** - cloud ${ov.pillar_none_by_deployment.cloud}%, self-hosted ${ov.pillar_none_by_deployment.self_hosted}%.`);
M.push('');
M.push(mdTable(PILLAR_COLS, pillarRows));
M.push('');
if (anyConfigureOnce) { M.push(`_${CONFIGURE_ONCE_FOOTNOTE}_`); M.push(''); }
M.push('_"Differs by deployment" is shown only where the difference survived testing. `*` p<0.05, `**` p<0.01, `***` p<0.001._');
M.push('');
