M.push('');
M.push(mdTable(SCORE_COLS, scoreRows));
M.push('');
M.push('_Change since last month: `*` p<0.05, `**` p<0.01, `***` p<0.001. No stars means the change is within normal month-to-month variation for a group that size._');
if (suppressedAliases.length) M.push(`_Rows omitted as exact duplicates of another group: ${suppressedAliases.join('; ')}._`);
M.push('');
M.push('## What each group talks about differently');
