    M.push('');
    M.push(`**${DIM_LABEL[dim]}** - ${s(nar.narrative)}`);
  }
}
M.push('');
M.push('## Method and caveats');
M.push('');
M.push(`Themes are assigned from a fixed codebook of ${n(themes.codebook_size)} curated themes; the model only assigns, it never counts and never invents a theme. Segment differences were selected by two-proportion tests in code: ${st.tests_run} comparisons run, ${st.tests_passed} survived Benjamini-Hochberg correction at FDR ${st.fdr_q}. Groups under ${st.min_segment_rows} classified responses are never tested.`);
if (st.coverage_pct < 100) M.push(`\n**Coverage ${st.coverage_pct}%.** ${num(st.uncaptured_rows)} of ${num(st.classified_rows)} comments predate segmentation capture and are excluded from Part 2.`);
M.push('');
M.push(`- **Part 1 covers only the ${overallScore ? n(overallScore.pct_with_text) : 0}% who wrote text**, and those people score ${overallScore ? n(overallScore.writer_bias) : 0} points higher than people who left the box empty. That does not just deflate counts, it tilts the ranking. The score tables are the unbiased part.`);
M.push('- **Changes and gaps are different.** A change is movement since last month. "vs average" is where a group sits relative to everyone, usually long-standing.');
M.push('- **NA means asked-and-unanswered**, not missing. Non-response is much higher among self-hosted users, so role and company-size rows lean cloud.');
M.push('- **Technical skills is cloud-only.** Every self-hosted row is NA by construction, never "zero skills".');
if (n(ov.quality.approx_timestamp_rows) > 0) M.push(`- **${num(ov.quality.approx_timestamp_rows)} rows carry an approximate response date** (within ~12 hours), from before the pipeline captured answer time.`);
M.push('');
M.push(`_Comments ${num(ov.driver_responses)} \u00b7 unassigned requests ${themes.unassigned ? themes.unassigned.request.pct : 0}% \u00b7 unassigned complaints ${themes.unassigned ? themes.unassigned.complaint.pct : 0}% \u00b7 unmatched ${n(ov.quality.unmatched_rows)} \u00b7 invalid categories ${n(ov.quality.enum_violation_rows)} \u00b7 filed as Other ${n(ov.quality.other_rows)} \u00b7 taxonomy ${ov.quality.strategy_versions.join(', ') || 'unknown'} \u00b7 segmentation coverage ${st.coverage_pct}%_`);
const notion_markdown = M.join('\n');

// ================= HTML EMAIL =================
const H = [];
H.push('<div style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;font-size:14px;color:#111;max-width:900px;">');
