if (overallScore) H.push(`<p style="font-size:15px;"><strong>NPS ${n(overallScore.nps)}</strong> from ${num(overallScore.responses)} responses \u00b7 ${num(overallScore.promoters)} promoters, ${num(overallScore.passives)} passives, ${num(overallScore.detractors)} detractors \u00b7 ${n(overallScore.pct_with_text)}% wrote open text.</p>`);
H.push('<h1 style="font-size:18px;border-top:2px solid #333;padding-top:10px;">Part 1 &mdash; Everyone</h1>');
