H.push(htmlTable(PILLAR_COLS, pillarRows));
if (anyConfigureOnce) H.push(`<p style="color:#555;font-size:12px;">${esc(CONFIGURE_ONCE_FOOTNOTE)}</p>`);
H.push('<p style="color:#555;font-size:12px;">"Differs by deployment" is shown only where the difference survived testing. * p&lt;0.05, ** p&lt;0.01, *** p&lt;0.001.</p>');
H.push('<h1 style="font-size:18px;border-top:2px solid #333;padding-top:10px;">Part 2 &mdash; By segment</h1>');
H.push('<h2 style="font-size:16px;">Scores</h2>');
H.push('<p style="color:#555;">Across ALL responses including the majority who wrote nothing, so unlike the topic tables these are not distorted by the open-text writer bias.</p>');
H.push(htmlTable(SCORE_COLS, scoreRows));
H.push('<p style="color:#555;font-size:12px;">Change since last month: * p&lt;0.05, ** p&lt;0.01, *** p&lt;0.001. No stars means the change is within normal month-to-month variation for a group that size.</p>');
if (suppressedAliases.length) H.push(`<p style="color:#555;font-size:12px;">Rows omitted as exact duplicates of another group: ${esc(suppressedAliases.join('; '))}.</p>`);
H.push('<h2 style="font-size:16px;">What each group talks about differently</h2>');
H.push(`<p style="color:#555;">Significance after Benjamini-Hochberg correction across all ${st.tests_run} comparisons. "Survives deployment check" = still holds when cloud and self-hosted are looked at separately; NO means the difference is real but caused by deployment, not by this segment.</p>`);
H.push(htmlTable(FINDING_COLS, findingRows));
if (anyNarrative) {
  H.push('<h2 style="font-size:16px;">Notes per segment</h2><ul>');
  for (const dim of Object.keys(DIM_LABEL)) {
    const nar = byDim[dim];
    if (!nar || !s(nar.narrative)) continue;
    H.push(`<li><strong>${esc(DIM_LABEL[dim])}</strong> - ${esc(s(nar.narrative))}</li>`);
  }
  H.push('</ul>');
}
H.push('<h2 style="font-size:16px;">Method and caveats</h2>');
H.push(`<p>Themes are assigned from a fixed codebook of ${n(themes.codebook_size)} curated themes; the model only assigns, it never counts and never invents a theme. Segment differences were selected by two-proportion tests in code: ${st.tests_run} comparisons run, ${st.tests_passed} survived Benjamini-Hochberg correction at FDR ${st.fdr_q}.</p>`);
if (st.coverage_pct < 100) H.push(`<p><strong>Coverage ${st.coverage_pct}%.</strong> ${num(st.uncaptured_rows)} of ${num(st.classified_rows)} comments predate segmentation capture and are excluded from Part 2.</p>`);
H.push('<ul>');
H.push(`<li><strong>Part 1 covers only the ${overallScore ? n(overallScore.pct_with_text) : 0}% who wrote text</strong>, who score ${overallScore ? n(overallScore.writer_bias) : 0} points higher than those who did not. That tilts the ranking, not just the counts.</li>`);
H.push('<li><strong>NA means asked-and-unanswered.</strong> Non-response is much higher among self-hosted users, so role and company-size rows lean cloud.</li>');
H.push('<li><strong>Technical skills is cloud-only.</strong> Every self-hosted row is NA by construction, never "zero skills".</li>');
H.push('</ul>');
H.push(`<p style="color:#777;font-size:12px;">Comments ${num(ov.driver_responses)} &middot; unassigned requests ${themes.unassigned ? themes.unassigned.request.pct : 0}% &middot; unassigned complaints ${themes.unassigned ? themes.unassigned.complaint.pct : 0}% &middot; unmatched ${n(ov.quality.unmatched_rows)} &middot; invalid categories ${n(ov.quality.enum_violation_rows)} &middot; filed as Other ${n(ov.quality.other_rows)} &middot; taxonomy ${esc(ov.quality.strategy_versions.join(', ') || 'unknown')} &middot; segmentation coverage ${st.coverage_pct}%</p>`);
H.push('</div>');
const email_html = H.join('\n');

return [{ json: {
  title: `NPS monthly report - ${period}`,
  period_label: period,
  slack_text, notion_markdown, email_html, email_text: notion_markdown, results,
  notion_main_page_url: NOTION_MAIN_PAGE_URL,
  notion_monthly_db_url: NOTION_MONTHLY_DB_URL,
  dimensions_failed: failed,
} }];

// Builds a COMPACT prompt. Only certified contrasts and the evidence needed to
// describe them are sent - never the raw rows. Keeps the call small enough to
// stay well inside the task-runner timeout that the monthly digest kept hitting.
const d = $json;
const MAX_QUOTES = 3;

const values = d.values.map((v) => ({
  value: v.value,
  rows: v.rows,
  testable: v.testable,
  suppressed_reason: v.suppressed_reason,
  nps: v.score ? v.score.nps : null,
  nps_responses: v.score ? v.score.responses : null,
  score_reliable: v.score ? v.score.score_reliable : null,
  sentimentCounts: v.sentimentCounts,
  requestPhrases: v.requestPhrases.slice(0, 10),
  problemPhrases: v.problemPhrases.slice(0, 10),
  quoteCandidates: v.quoteCandidates.slice(0, MAX_QUOTES),
}));

const payload = {
  dimension: d.dimension,
  period: d.period_label,
  certified_contrasts: d.certified,
  values,
  coverage_pct: d.stats.coverage_pct,
  tests_run: d.stats.tests_run,
  tests_passed: d.stats.tests_passed,
};

return [{ json: { dimension: d.dimension, promptText: JSON.stringify(payload) } }];

// Parse defensively and NEVER throw. A single dimension failing to return JSON
// must not lose the other four - the failure is recorded and rendered as a
// visible gap in the report instead.
const raw = $json.output ?? $json.text ?? '';
const dimension = $('Build Dimension Prompt').first().json.dimension;

let parsed = null;
let parseError = '';
try {
  const cleaned = String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) { parseError = e.message; }

if (!parsed || typeof parsed !== 'object') {
  return [{ json: { dimension, parse_ok: false, parseError, narrative: '', findings: [] } }];
}

return [{ json: {
  dimension,
  parse_ok: true,
  parseError: '',
  narrative: typeof parsed.narrative === 'string' ? parsed.narrative : '',
  findings: Array.isArray(parsed.findings) ? parsed.findings : [],
} }];

// Builds the clustering call. The codebook is FIXED: themes are curated in the
// nps_theme_codebook data table and this workflow never writes to it. That is
// what makes months comparable - the same phrase means the same theme in July
// and in August, because the theme set did not move underneath it.
const codebook = $input.all().map((i) => i.json).filter((r) => r && r.theme_id);
if (!codebook.length) throw new Error('The theme codebook is empty. Add active themes to nps_theme_codebook before running - this workflow assigns to existing themes and never invents its own.');

const rows = $('Fetch Period Insights (Segmented)').all().map((i) => i.json);
const norm = (s) => String(s).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '').replace(/\s+/g, ' ').trim();
const valid = (ev) => ev && ev !== 'UNMATCHED_BY_CLASSIFIER' && !String(ev).startsWith('ENUM_VIOLATION');

// Collapse identical phrasings first, so the model clusters a few hundred
// distinct strings rather than every row. The count travels with each phrase
// and is NEVER recomputed from the model's output.
function collect(kind) {
  const m = new Map();
  for (const r of rows) {
    const ev = String(r.evidence || '').trim();
    if (!valid(ev)) continue;
    const isReq = r.is_request === true;
    if (kind === 'request' && !isReq) continue;
    if (kind === 'complaint' && (isReq || r.sentiment !== 'negative')) continue;
    const k = norm(ev);
    if (!k) continue;
    if (!m.has(k)) m.set(k, { text: ev, count: 0, npsSum: 0 });
    const e = m.get(k);
    e.count++;
    e.npsSum += Number(r.nps) || 0;
  }
  return [...m.values()]
    .map((e) => ({ text: e.text, count: e.count, avg_nps: Math.round(e.npsSum / e.count * 10) / 10 }))
    .sort((a, b) => b.count - a.count);
}

const requests = collect('request');
const complaints = collect('complaint');

// Defensive cap. July had ~170 distinct requests, so this is headroom rather
// than a real limit - but an unbounded list is what pushed an earlier
// summariser past a 10 minute timeout.
const CAP = 400;
const phrases = [
  ...requests.slice(0, CAP).map((p, i) => ({ id: `r${i}`, kind: 'request', ...p })),
  ...complaints.slice(0, CAP).map((p, i) => ({ id: `c${i}`, kind: 'complaint', ...p })),
];
if (!phrases.length) throw new Error('No request or complaint phrases found for this period.');

const payload = {
  codebook: codebook.map((t) => ({ theme_id: t.theme_id, label: t.label, kind: t.kind, description: t.description, examples: t.examples })),
  phrases,
};

console.log('[Themes] ' + codebook.length + ' active themes, ' + requests.length + ' distinct requests, ' + complaints.length + ' distinct complaints');

return [{ json: { codebook_size: codebook.length, phrase_count: phrases.length, promptText: JSON.stringify(payload) } }];

// The model clusters. THIS CODE COUNTS. Every phrase id the model returns is
// checked against the list we sent; anything invented is dropped. Counts come
// from the phrase counts computed upstream, never from the model.
const raw = $json.output ?? $json.text ?? '';
const sent = JSON.parse($('Build Theme Prompt').first().json.promptText);
const byId = {};
for (const p of sent.phrases) byId[p.id] = p;
const known = new Map();
for (const t of sent.codebook) known.set(t.theme_id, t);

let parsed = null, parseError = '';
try {
  parsed = JSON.parse(String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim());
} catch (e) { parseError = e.message; }

const totals = { request: 0, complaint: 0 };
for (const p of sent.phrases) totals[p.kind] += p.count;

// Never throw: a failed clustering must not lose the rest of the report.
if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.assignments)) {
  return [{ json: {
    ok: false, parseError: parseError || 'no assignments array returned',
    request_themes: [], complaint_themes: [],
    unassigned: { request: { mentions: totals.request, total: totals.request, pct: 100 }, complaint: { mentions: totals.complaint, total: totals.complaint, pct: 100 } },
    alert: false, alert_threshold_pct: 15, dropped_phrase_ids: 0, invented_themes: 0, codebook_size: sent.codebook.length,
  } }];
}

// A phrase MAY belong to several themes ('cheaper key to unlock features while
// self-hosting' is genuinely pricing AND self-hosting). Consequence: theme
// shares do NOT sum to 100%, and the report says so rather than implying a
// partition.
const tally = new Map();
const seenPhrase = new Set();
const assignedMentions = { request: 0, complaint: 0 };
let droppedIds = 0, inventedThemes = 0;

for (const a of parsed.assignments) {
  const p = byId[a && a.phrase_id];
  if (!p) { droppedIds++; continue; }
  const ids = Array.isArray(a.theme_ids) ? a.theme_ids : [];
  const realIds = [];
  for (const id of ids) {
    if (!id || id === 'unassigned') continue;
    // The codebook is curated. A theme id we never sent is a hallucination and
    // is discarded rather than silently entering the report.
    if (!known.has(id)) { inventedThemes++; continue; }
    // A request phrase can never belong to a complaint theme or the reverse.
    if ((known.get(id).kind || 'request') !== p.kind) continue;
    realIds.push(id);
  }
  if (!realIds.length) continue;
  if (!seenPhrase.has(p.id)) { seenPhrase.add(p.id); assignedMentions[p.kind] += p.count; }
  for (const id of realIds) {
    if (!tally.has(id)) tally.set(id, { theme_id: id, mentions: 0, phrases: 0, npsSum: 0, samples: [] });
    const t = tally.get(id);
    t.mentions += p.count;
    t.phrases += 1;
    t.npsSum += (p.avg_nps || 0) * p.count;
    if (t.samples.length < 3) t.samples.push(p.text);
  }
}

const dress = (kind) => [...tally.values()]
  .map((t) => ({ ...t, meta: known.get(t.theme_id) }))
  .filter((t) => t.meta && (t.meta.kind || 'request') === kind)
  .map((t) => ({
    theme_id: t.theme_id, label: t.meta.label, mentions: t.mentions, distinct_phrases: t.phrases,
    share_pct: totals[kind] ? Math.round(1000 * t.mentions / totals[kind]) / 10 : 0,
    avg_nps: t.mentions ? Math.round(t.npsSum / t.mentions * 10) / 10 : 0,
    samples: t.samples,
  }))
  .sort((a, b) => b.mentions - a.mentions);

const mk = (kind) => ({
  mentions: totals[kind] - assignedMentions[kind], total: totals[kind],
  pct: totals[kind] ? Math.round(1000 * (totals[kind] - assignedMentions[kind]) / totals[kind]) / 10 : 0,
});
const unassigned = { request: mk('request'), complaint: mk('complaint') };

// The alert. Unassigned is not a failure - it is the signal that users have
// started talking about something the curated codebook does not yet cover.
const ALERT_THRESHOLD_PCT = 15;
const alert = unassigned.request.pct > ALERT_THRESHOLD_PCT || unassigned.complaint.pct > ALERT_THRESHOLD_PCT;

console.log('[Themes] ' + dress('request').length + ' request themes, ' + dress('complaint').length + ' complaint themes, unassigned ' + unassigned.request.pct + '% requests / ' + unassigned.complaint.pct + '% complaints' + (droppedIds ? ', ' + droppedIds + ' invented phrase ids dropped' : '') + (inventedThemes ? ', ' + inventedThemes + ' invented theme ids dropped' : ''));
if (alert) console.warn('[Themes] ALERT: unassigned share above ' + ALERT_THRESHOLD_PCT + '% - the codebook may need a new theme');

return [{ json: {
  ok: true, parseError: '',
  request_themes: dress('request'), complaint_themes: dress('complaint'),
  unassigned, alert, alert_threshold_pct: ALERT_THRESHOLD_PCT,
  dropped_phrase_ids: droppedIds, invented_themes: inventedThemes, codebook_size: sent.codebook.length,
} }];

// Converts the structured results into Notion blocks.
// Notion has no markdown endpoint, so this walks the SAME `results` object the
// email renders from rather than parsing markdown - the data was built
// storage-agnostic precisely so a new destination needs a renderer, not a
// rewrite.
//
// The score headline and the caveat sentences are read from the engine and the
// score bundle directly, because they are prose the email builds inline rather
// than rows inside `results`. An earlier version omitted them and the Notion
// page silently lost the NPS headline and the no-bet share.
const d = $json;
const r = d.results || {};
const engine = $('Segment Contrast Engine').first().json;
const bundle = $('Collect Segment Scores').first().json;
const ov = engine.overall || {};
const st = engine.stats || {};
const overallScore = (bundle.scores || []).find((x) => x.segment_dim === 'overall');

const n = (v) => { const x = typeof v === 'string' ? Number(v) : v; return (typeof x === 'number' && isFinite(x)) ? x : 0; };
const num = (v) => n(v).toLocaleString('en-US');

const txt = (content) => ({ type: 'text', text: { content: String(content ?? '').slice(0, 2000) } });
const para = (content, opts = {}) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: [{ ...txt(content), annotations: opts }] } });
const heading = (content, level) => ({ object: 'block', type: `heading_${level}`, [`heading_${level}`]: { rich_text: [txt(content)] } });
const callout = (content) => ({ object: 'block', type: 'callout', callout: { rich_text: [txt(content)], icon: { type: 'emoji', emoji: '\u26A0\uFE0F' } } });
const bullet = (content) => ({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: [txt(content)] } });
const divider = () => ({ object: 'block', type: 'divider', divider: {} });

// Notion caps nested children per request, so a long table is split into
// several table blocks rather than failing outright. The header row is
// repeated on each chunk so a split table still reads correctly.
const MAX_ROWS = 90;
function table(cols, rows) {
  if (!rows || !rows.length) return [para('Nothing to show.', { italic: true })];
  const row = (cells) => ({ object: 'block', type: 'table_row', table_row: { cells: cells.map((c) => [txt(c)]) } });
  const header = cols.map((c) => c.label);
  const out = [];
  for (let i = 0; i < rows.length; i += MAX_ROWS) {
    const slice = rows.slice(i, i + MAX_ROWS);
    out.push({
      object: 'block', type: 'table',
      table: {
        table_width: cols.length, has_column_header: true, has_row_header: false,
        children: [row(header), ...slice.map((x) => row(cols.map((c) => x[c.key] ?? '')))],
      },
    });
  }
  return out;
}

const TOPIC_COLS = [{ key: 'topic', label: 'Topic' }, { key: 'mentions', label: 'Mentions' }, { key: 'share', label: 'Share' }, { key: 'sentiment', label: 'Sentiment' }, { key: 'bands', label: 'Detr / Pass / Prom' }, { key: 'note', label: 'Notes' }];
const THEME_COLS = [{ key: 'theme', label: 'Theme' }, { key: 'mentions', label: 'Mentions' }, { key: 'share', label: 'Share' }, { key: 'phrases', label: 'Distinct phrasings' }, { key: 'avg', label: 'Avg NPS' }, { key: 'examples', label: 'Examples' }];
const PILLAR_COLS = [{ key: 'bet', label: 'Strategic bet' }, { key: 'mentions', label: 'Mentions' }, { key: 'share', label: 'Share' }, { key: 'sentiment', label: 'Sentiment' }, { key: 'split', label: 'Differs by deployment' }, { key: 'note', label: 'Notes' }];
const SCORE_COLS = [{ key: 'dimension', label: 'Segment' }, { key: 'group', label: 'Group' }, { key: 'responses', label: 'Responses' }, { key: 'nps', label: 'NPS' }, { key: 'vs_average', label: 'vs average' }, { key: 'change', label: 'Change' }, { key: 'wrote_text', label: 'Wrote text' }, { key: 'comments', label: 'Comments' }];
const FINDING_COLS = [{ key: 'dimension', label: 'Segment' }, { key: 'group', label: 'Group' }, { key: 'topic', label: 'Topic' }, { key: 'direction', label: 'More/less' }, { key: 'this_group', label: 'This group' }, { key: 'everyone_else', label: 'Everyone else' }, { key: 'responses', label: 'n' }, { key: 'sig', label: 'Sig.' }, { key: 'real_effect', label: 'Survives check' }];

const th = r.themes || {};
const un = th.unassigned || {};
const blocks = [];

// Space reserved at the top for the summary, written by the summary workflow.
blocks.push(heading('Summary', 2));
blocks.push(para('To be written.', { italic: true }));

if (th.alert) {
  const parts = [];
  if (un.request && un.request.pct > th.alert_threshold_pct) parts.push(`${un.request.pct}% of requests`);
  if (un.complaint && un.complaint.pct > th.alert_threshold_pct) parts.push(`${un.complaint.pct}% of complaints`);
  blocks.push(callout(`${parts.join(' and ')} did not fit any theme in the codebook (threshold ${th.alert_threshold_pct}%). Review the unassigned rows before treating this month as final - they may need a new theme.`));
}
if (th.ok === false) blocks.push(callout('Theme clustering failed this run, so the request and complaint tables are empty. Everything else is unaffected.'));

// The score headline, which the Notion page was missing entirely.
if (overallScore) {
  blocks.push(para(`NPS ${n(overallScore.nps)} from ${num(overallScore.responses)} responses \u00b7 ${num(overallScore.promoters)} promoters, ${num(overallScore.passives)} passives, ${num(overallScore.detractors)} detractors \u00b7 ${n(overallScore.pct_with_text)}% wrote open text.`, { bold: true }));
}

blocks.push(divider());
blocks.push(heading('Part 1 - Everyone', 1));
blocks.push(heading('What they talked about', 2));
blocks.push(para(`From the ${num(ov.driver_responses)} comments with substantive text.`, { italic: true }));
blocks.push(...table(TOPIC_COLS, r.topics));

blocks.push(heading('What they asked for', 2));
blocks.push(...table(THEME_COLS, r.requests));
blocks.push(para('Themes come from a fixed codebook, so they mean the same thing month to month. A comment can mention more than one theme, so shares do not add up to 100% - each is the share of comments mentioning that theme.', { italic: true }));

blocks.push(heading('What they struggle with', 2));
blocks.push(para('Negative-sentiment evidence. Distinct from requests above: things people described as problems, not things they asked for.', { italic: true }));
blocks.push(...table(THEME_COLS, r.complaints));

blocks.push(heading('Strategic bets', 2));
// The no-bet share: how much of what users said touches nothing we are betting
// on. This was missing from the Notion page and is one of the more loaded
// numbers in the report.
blocks.push(para(`${num(ov.pillar_none_count)} comments (${ov.pillar_none_share_pct}%) touched no current strategic bet - cloud ${ov.pillar_none_by_deployment ? ov.pillar_none_by_deployment.cloud : 0}%, self-hosted ${ov.pillar_none_by_deployment ? ov.pillar_none_by_deployment.self_hosted : 0}%.`, { bold: true }));
blocks.push(...table(PILLAR_COLS, r.bets));
if ((ov.pillars || []).some((p) => p.configure_once)) {
  blocks.push(para('\u2020 Configure-once surface: users touch it rarely, so it generates almost no unprompted comment however important it is. A zero here is expected and is not a health signal - source these from sales, support and CS instead.', { italic: true }));
}
blocks.push(para('"Differs by deployment" is shown only where the difference survived testing. * p<0.05, ** p<0.01, *** p<0.001.', { italic: true }));

blocks.push(divider());
blocks.push(heading('Part 2 - By segment', 1));
blocks.push(heading('Scores', 2));
blocks.push(para('Across ALL responses including the majority who wrote nothing, so unlike the topic tables these are not distorted by the open-text writer bias.', { italic: true }));
blocks.push(...table(SCORE_COLS, r.scores));
blocks.push(para('Change since last month: * p<0.05, ** p<0.01, *** p<0.001. No stars means the change is within normal month-to-month variation for a group that size.', { italic: true }));

blocks.push(heading('What each group talks about differently', 2));
blocks.push(para(`Significance after Benjamini-Hochberg correction across all ${st.tests_run} comparisons. "Survives check" = still holds when cloud and self-hosted are looked at separately; NO means the difference is real but caused by deployment, not by this segment.`, { italic: true }));
blocks.push(...table(FINDING_COLS, r.findings));

blocks.push(divider());
blocks.push(heading('Method and caveats', 2));
blocks.push(para(`Themes are assigned from a fixed codebook of ${n(th.codebook_size)} curated themes; the model only assigns, it never counts and never invents a theme. Segment differences were selected by two-proportion tests in code: ${st.tests_run} comparisons run, ${st.tests_passed} survived correction. Groups under ${st.min_segment_rows} classified responses are never tested.`));
if (st.coverage_pct < 100) {
  blocks.push(para(`Coverage ${st.coverage_pct}%. ${num(st.uncaptured_rows)} of ${num(st.classified_rows)} comments predate segmentation capture and are excluded from Part 2.`));
}
blocks.push(bullet(`Part 1 covers only the ${overallScore ? n(overallScore.pct_with_text) : 0}% who wrote open text, and those people score ${overallScore ? n(overallScore.writer_bias) : 0} points higher than people who left the box empty. That does not just deflate counts, it tilts the ranking. The score tables are the unbiased part.`));
blocks.push(bullet('Changes and gaps are different. A change is movement since last month. "vs average" is where a group sits relative to everyone, usually long-standing.'));
blocks.push(bullet('NA means asked-and-unanswered, not missing. Non-response is much higher among self-hosted users, so role and company-size rows lean cloud.'));
blocks.push(bullet('Technical skills is a cloud-only question. Every self-hosted row is NA by construction, never "zero skills".'));
if (n(ov.quality && ov.quality.approx_timestamp_rows) > 0) {
  blocks.push(bullet(`${num(ov.quality.approx_timestamp_rows)} rows carry an approximate response date (within ~12 hours), from before the pipeline captured answer time.`));
}
blocks.push(para(`Comments ${num(ov.driver_responses)} \u00b7 unassigned requests ${un.request ? un.request.pct : 0}% \u00b7 unassigned complaints ${un.complaint ? un.complaint.pct : 0}% \u00b7 unmatched ${n(ov.quality && ov.quality.unmatched_rows)} \u00b7 filed as Other ${n(ov.quality && ov.quality.other_rows)} \u00b7 segmentation coverage ${st.coverage_pct}%`, { italic: true }));

// Notion accepts at most 100 blocks per request, so the page is created with
// the first chunk and the rest are appended.
const CHUNK = 90;
const chunks = [];
for (let i = 0; i < blocks.length; i += CHUNK) chunks.push(blocks.slice(i, i + CHUNK));

console.log('[Notion] ' + blocks.length + ' blocks in ' + chunks.length + ' chunk(s)');

return [{ json: {
  title: d.title,
  first_chunk: chunks[0] || [],
  rest: chunks.slice(1),
  block_count: blocks.length,
  chunk_count: chunks.length,
} }];

// One item per remaining chunk, each carrying the new page id. Emits nothing
// when the report fitted in a single request, in which case the append node
// simply does not run.
const page = $json;
const prep = $('Build Notion Blocks').first().json;
const pageId = page.id;
if (!pageId) throw new Error('Notion did not return a page id: ' + JSON.stringify(page).slice(0, 300));
console.log('[Notion] page created ' + (page.url || pageId) + ', appending ' + (prep.rest || []).length + ' further chunk(s)');
return (prep.rest || []).map((chunk) => ({ json: { page_id: pageId, page_url: page.url || '', children: chunk } }));

